// Small helpers shared by the page renderers: tables, links, Mermaid text. Pure functions of the model.
import {
  Array as Arr,
  Option,
  Order,
  Record as Rec,
  String as Str,
} from "effect";

import type { Item, Model } from "../model.ts";
import { sourceLabel, sourceUrl, parseSource } from "../refs.ts";
import { kindInfo } from "../vocabulary.ts";
import type { Scope, SubModel } from "../vocabulary.ts";

export const generatedNotice =
  "<!-- Generated by tools/intent from model/. Do not edit by hand: change the model and run `bun run generate`. -->";

/** The page of a sub-model, relative to `docs/`. */
export const subModelPages: Readonly<Record<SubModel, string>> = {
  actors: "actors-and-resources.md",
  concepts: "concepts.md",
  goals: "goals.md",
  processes: "business-processes.md",
  rules: "business-rules.md",
  technical: "technical-components.md",
};

export const scopeTitles: Readonly<Record<Scope, string>> = {
  "foldkit-flow": "foldkit-flow",
  org: "The organisation",
  reebeat: "reebeat (the compiler)",
  studio: "reebeat studio",
};

/** Link target of an item from a page in `docs/` (prefix "") or in `docs/products/` (prefix "../"). */
export const href = (item: Item, prefix: string): string =>
  `${prefix}${subModelPages[kindInfo[item.kind].subModel]}#${item.id}`;

const escapeCell = (text: string): string =>
  Str.replaceAll("\n", " ")(Str.replaceAll("|", "\\|")(text));

export const oneLine = (text: string): string =>
  Str.replaceAll(/\s+/gu, " ")(Str.trim(text));

export const table = (
  header: readonly string[],
  rows: readonly (readonly string[])[]
): string =>
  Arr.join(
    [
      `| ${Arr.join(header, " | ")} |`,
      `| ${Arr.join(
        Arr.map(header, () => "---"),
        " | "
      )} |`,
      ...Arr.map(
        rows,
        (row) => `| ${Arr.join(Arr.map(row, escapeCell), " | ")} |`
      ),
    ],
    "\n"
  );

export const titleLink = (item: Item, prefix: string): string =>
  `[${escapeCell(item.title)}](${href(item, prefix)})`;

/** Markdown links to the cited evidence. */
export const sourceLinks = (model: Model, item: Item, prefix: string): string =>
  Arr.join(
    Arr.map(item.source, (text) =>
      Option.match(parseSource(text), {
        onNone: () => text,
        onSome: (source) =>
          `[${sourceLabel(source)}](${sourceUrl(source, model.sources.repos, model.sources.decisionLog, `${prefix}../`)})`,
      })
    ),
    ", "
  );

export const linkSummary = (
  item: Item,
  byId: ReadonlyMap<string, Item>,
  prefix: string
): string =>
  Arr.join(
    Arr.map(Rec.toEntries(item.links ?? {}), ([type, targets]) => {
      const names = Arr.map(targets, (id) => {
        const target = byId.get(id);

        return target === undefined ? id : titleLink(target, prefix);
      });

      return `${type}: ${Arr.join(names, ", ")}`;
    }),
    "; "
  );

const statusOrder = Order.mapInput(
  Order.Number,
  (item: Item) => ({ decided: 0, open: 2, proposed: 1 })[item.status]
);

export const byStatus = (items: readonly Item[]): readonly Item[] =>
  Arr.sort(items, statusOrder);

export const anchor = (item: Item): string => `<a id="${item.id}"></a>`;

export const statusCounts = (
  items: readonly Item[]
): Readonly<Record<"decided" | "proposed" | "open", number>> => ({
  decided: Arr.filter(items, (item) => item.status === "decided").length,
  open: Arr.filter(items, (item) => item.status === "open").length,
  proposed: Arr.filter(items, (item) => item.status === "proposed").length,
});

/** A Mermaid-safe node id. */
export const nodeId = (id: string): string => Str.replaceAll("-", "_")(id);

/** A Mermaid-safe quoted label; long labels wrap at spaces. */
export const label = (text: string): string => {
  const clean = Str.replaceAll(
    '"',
    "'"
  )(Str.replaceAll(/[<>[\]{}|]/gu, "")(text));

  const words = Str.split(" ")(clean);

  const lines = Arr.reduce(words, Arr.empty<string>(), (acc, word) => {
    const last = acc.at(-1);

    return last !== undefined && last.length + word.length < 28
      ? [...acc.slice(0, -1), `${last} ${word}`]
      : [...acc, word];
  });

  return Arr.join(lines, "<br/>");
};

export const statusClassDefs = Arr.join(
  [
    "classDef decided fill:#d8f0d8,stroke:#2d7a2d,color:#111",
    "classDef proposed fill:#fff3c4,stroke:#a07800,color:#111",
    "classDef open fill:#f8d7d7,stroke:#a02020,color:#111",
    "classDef outside fill:#eee,stroke:#999,color:#333,stroke-dasharray:4 3",
  ],
  "\n    "
);

export const mermaid = (body: string): string =>
  `\`\`\`mermaid\n${body}\n\`\`\``;

export const itemsOfScope = (
  items: readonly Item[],
  scope: Scope
): readonly Item[] => Arr.filter(items, (item) => item.scope === scope);

export const inSubModel = (
  items: readonly Item[],
  subModel: SubModel
): readonly Item[] =>
  Arr.filter(items, (item) => kindInfo[item.kind].subModel === subModel);
